const fs = require('fs');
const path = require('path');

// ============================================================
// generar_465_cotutor_y_ortografia.js
// ============================================================
// Tres cosas.
//
// 1. CO-TUTOR — lo reportaron los usuarios
//    Preguntar "¿como creo un cotutor?" respondia "no se", porque solo
//    estaban las formas indirectas ("otra persona", "mi pareja") y no
//    la palabra misma. Ahora reconoce cotutor, co-tutor, co tutor,
//    cuidador, segunda persona y codigo de invitacion.
//
//    Y el guion se normaliza: "co-tutor" y "co tutor" son lo mismo para
//    quien pregunta, y no deberia importar como lo escriba.
//
// 2. "¿QUIZAS QUISISTE DECIR...?"
//    Compara por distancia de edicion: cuantas letras hay que cambiar
//    de una palabra a otra. "desparaCitada" a "desparaSitada" es una
//    sola, asi que se ofrece:
//
//      Tú: desparacitacion
//      Chiqui: No estoy segura de qué quieres consultar 🐾
//              ¿Quizás quisiste preguntar esto?
//              [¿Cuándo le toca la próxima desparasitación?]
//              [No, era otra cosa]
//
//    DOS DECISIONES IMPORTANTES:
//
//    Solo se usa cuando el clasificador YA SE RINDIO. Nunca antes: si
//    corrigiera de entrada podria "arreglar" una palabra que estaba
//    bien y mandar la pregunta a otra categoria.
//
//    Y PREGUNTA, no corrige en silencio. Corregir sin avisar significa
//    responder sobre algo que la persona no pregunto, con la misma
//    seguridad de siempre.
//
//    El margen crece con el largo de la palabra: en una de 15 letras un
//    par de erratas es normal; en una de 5, dos ya la vuelven otra
//    palabra. Por eso "programar" no sugiere nada — y esta bien.
//
// 3. EL FLOTANTE YA ABRE CONTANDO
//    En las pantallas que no son Analisis, el chat saludaba sin el
//    resumen de lo que paso, porque ese calculo solo existia en
//    Analisis. Ahora los episodios se arman desde las señales que el
//    flotante ya carga.
//
// REQUISITOS: scripts 463 y 464 desplegados.
//
// Si algo no calza, ABORTA sin escribir NADA.
// ============================================================

const RUTA_CHAT = 'components/ChiquiChat.tsx';
const RUTA_FLOT = 'components/ChiquiFlotante.tsx';
const CHAT_B64 = '';
const FLOT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico NINGUN archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const dChat = path.join(process.cwd(), RUTA_CHAT);
const dFlot = path.join(process.cwd(), RUTA_FLOT);
for (const [r, d] of [[RUTA_CHAT, dChat], [RUTA_FLOT, dFlot]]) {
  if (!fs.existsSync(d)) abortar('no se encontro ' + r + '.');
}

const actual = fs.readFileSync(dChat, 'utf8');
if (actual.includes('quisisteDecir')) {
  abortar('el chat ya tiene esto. Parece que este script ya se corrio.');
}
if (!actual.includes('CUIDADOS_CONOCIDOS')) {
  abortar('falta el script 464. Correlo primero.');
}

const chat = Buffer.from(CHAT_B64, 'base64').toString('utf8');
const flot = Buffer.from(FLOT_B64, 'base64').toString('utf8');

for (const r of ["'use client'", 'export default function ChiquiChat', 'function quisisteDecir',
                 'function distancia', 'const VOCABULARIO', "'co-tutor'", 'Quizás quisiste preguntar',
                 'CUIDADOS_CONOCIDOS']) {
  if (!chat.includes(r)) abortar('el chat nuevo no incluye [' + r + ']. Script corrupto.');
}
// La sugerencia TIENE que ir despues de todo lo demas.
if (chat.indexOf('const sugerido = quisisteDecir') < chat.indexOf("// --- 5. LA INTENCIÓN QUE MÁS COINCIDE ---")) {
  abortar('la sugerencia ortografica quedaria antes de la clasificacion: podria corregir palabras que estaban bien.');
}
console.log('  OK  la sugerencia va al final, solo si nada calzo');

for (const r of ["'use client'", 'export default function ChiquiFlotante', 'const episodios',
                 'episodios,', 'setInterval(revisar, 1500)']) {
  if (!flot.includes(r)) abortar('el flotante nuevo no incluye [' + r + ']. Script corrupto.');
}
console.log('  OK  el flotante calcula sus episodios');

fs.writeFileSync(dChat, chat, 'utf8');
console.log('');
console.log('OK: ' + RUTA_CHAT);
fs.writeFileSync(dFlot, flot, 'utf8');
console.log('OK: ' + RUTA_FLOT);
console.log('');
console.log('Listo. Prueba con "cotutor" y con una palabra mal escrita.');
